CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email VARCHAR(320) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE credit_accounts (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, balance INTEGER NOT NULL DEFAULT 0 CHECK (balance >= 0), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE credit_transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, amount INTEGER NOT NULL CHECK (amount <> 0), balance_after INTEGER NOT NULL CHECK (balance_after >= 0), kind VARCHAR(32) NOT NULL, idempotency_key VARCHAR(128) NOT NULL UNIQUE, reference_id VARCHAR(128), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_credit_transactions_user_created ON credit_transactions(user_id, created_at DESC);
CREATE TABLE generation_jobs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, status VARCHAR(24) NOT NULL DEFAULT 'queued', model VARCHAR(120) NOT NULL, prompt TEXT NOT NULL, parameters JSONB NOT NULL DEFAULT '{}'::jsonb, error_code VARCHAR(64), result_asset_id UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_generation_jobs_user_created ON generation_jobs(user_id, created_at DESC); CREATE INDEX ix_generation_jobs_status ON generation_jobs(status);
CREATE TABLE credit_reservations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, job_id UUID NOT NULL UNIQUE REFERENCES generation_jobs(id) ON DELETE CASCADE, reserved_amount INTEGER NOT NULL CHECK (reserved_amount > 0), settled_amount INTEGER, status VARCHAR(16) NOT NULL DEFAULT 'reserved', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE assets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, object_key VARCHAR(512) NOT NULL UNIQUE, mime_type VARCHAR(100) NOT NULL, size_bytes INTEGER NOT NULL CHECK (size_bytes > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX ix_assets_user_created ON assets(user_id, created_at DESC);
CREATE TABLE projects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, name VARCHAR(160) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX ix_projects_user_created ON projects(user_id, created_at DESC);
